import argparse
import csv
import math
import random
import sys


def read_csv(path):
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        fieldnames = reader.fieldnames
        rows = list(reader)
    return fieldnames, rows


def write_csv(path, fieldnames, rows):
    with open(path, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)


def sample_random(rows, n):
    return random.sample(rows, min(n, len(rows)))


def sample_stratified(rows, n, stratify_col):
    groups = {}
    for row in rows:
        key = row[stratify_col]
        groups.setdefault(key, []).append(row)

    total = len(rows)
    sampled = []
    for key, group in groups.items():
        group_n = max(1, round(n * len(group) / total))
        sampled.extend(random.sample(group, min(group_n, len(group))))

    # Trim or pad to exact n
    if len(sampled) > n:
        sampled = random.sample(sampled, n)
    return sampled


def sample_systematic(rows, n):
    if n >= len(rows):
        return list(rows)
    step = len(rows) / n
    start = random.uniform(0, step)
    indices = [int(start + i * step) for i in range(n)]
    return [rows[i] for i in indices]


def main():
    parser = argparse.ArgumentParser(description="Sample rows from a CSV file.")
    parser.add_argument("input", help="Path to input CSV file")
    parser.add_argument("n", type=int, help="Number of rows to sample")
    parser.add_argument(
        "-m",
        "--method",
        choices=["random", "stratified", "systematic"],
        default="random",
        help="Sampling strategy (default: random)",
    )
    parser.add_argument(
        "-s",
        "--stratify-column",
        help="Column to stratify by (required for stratified sampling)",
    )
    parser.add_argument(
        "-o", "--output", help="Output CSV path (default: stdout)"
    )
    parser.add_argument("--seed", type=int, help="Random seed for reproducibility")
    args = parser.parse_args()

    if args.method == "stratified" and not args.stratify_column:
        parser.error("--stratify-column is required for stratified sampling")

    if args.seed is not None:
        random.seed(args.seed)

    fieldnames, rows = read_csv(args.input)

    if args.n <= 0:
        print("Error: n must be a positive integer", file=sys.stderr)
        sys.exit(1)

    if args.method == "random":
        sampled = sample_random(rows, args.n)
    elif args.method == "stratified":
        sampled = sample_stratified(rows, args.n, args.stratify_column)
    else:
        sampled = sample_systematic(rows, args.n)

    if args.output:
        write_csv(args.output, fieldnames, sampled)
        print(f"Wrote {len(sampled)} rows to {args.output}", file=sys.stderr)
    else:
        writer = csv.DictWriter(sys.stdout, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(sampled)


if __name__ == "__main__":
    main()
